{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Perindoprilat, the active diacid metabolite of the ACE inhibitor prodrug perindopril, achieved 30 ± 6% oral availability in cirrhotic patients, directly supporting F ≥ 20% for an ACE inhibitor active species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Perindopril, an ethyl ester prodrug ACE inhibitor, has absolute oral bioavailability of 66–95% in fasted healthy/hypertensive subjects, showing that ACE inhibitor prodrugs can be well absorbed despite a free carboxylate in the active form.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Desethyloxybutynin metabolites have oral bioavailability 62–78% in healthy adults, supporting high F for ester-containing drugs, though less structurally related.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Captopril, a thiol-containing ACE inhibitor, has absolute oral bioavailability up to 91% and typically about 60% in fasting subjects, supporting high F for ACE inhibitors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Fosamprenavir, a phosphate ester prodrug, has human oral bioavailability 20–80%, supporting that ester prodrugs of polar acids can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PEMA, a small polar diamide, has near-complete oral bioavailability (91 ± 4.4%), supporting high F for small polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Temocaprilat, the active diacid of the prodrug temocapril, has absolute oral bioavailability about 65% after oral temocapril, directly supporting high F for ACE inhibitor active metabolites.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Omapatrilat, a dual ACE/NEP inhibitor with a free thiol and carboxylate, has absolute oral bioavailability about 30% (range 22–45%), supporting F ≥ 20% for structurally complex ACE inhibitor active forms.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Perindopril absolute oral bioavailability is about 75% (range 60–95%) in humans, strongly supporting high F for ACE inhibitor prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "BMS-187745, a highly polar phosphonic/sulfonic acid, has only 2.6% oral bioavailability; however, its very low transfer score (0.0027) and lack of a prodrug ester make it a weak contradictory anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphinic ester prodrug ACE inhibitor (fosinopril-like). Multiple high-transfer ACE inhibitor prodrugs and active metabolites (perindopril, captopril, temocapril, omapatrilat) show absolute oral bioavailability of 30–95%, all above the 20% threshold. The only low-F analogue is a highly polar phosphonic/sulfonic acid with negligible transfer. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct fosinopril bioavailability measurement is present in the provided evidence; prediction relies on close ACE inhibitor prodrug analogues.",
    "The exact effect of the phosphinic ester prodrug on absorption is inferred from related prodrugs, not directly measured for the query.",
    "The low-F phosphonic acid analogue is too dissimilar to weigh heavily."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

